-- Class notes synopsis batch 27 (final): Witch Hazel through Ylang Ylang

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Witch Hazel</strong> is an <strong>astringent</strong>, <strong>anti-inflammatory</strong>, and <strong>constricting</strong> herb (tannin-rich) documented in the African American Materia Medica. For <strong>cancer support</strong>: leaf in anti-cancer formula 1 to quickly change the environment in early-stage cancer; bark in anti-cancer formula 2 (more intense, used in later stages); cooling, anti-inflammatory, and tissue-healing support during chemotherapy — breaks up scar tissue as tea. For <strong>wounds</strong>: astringent and anti-inflammatory applied externally as tincture or liniment. For <strong>swimmer's ear</strong>: applied topically alongside ACV and <a href="?herb=81"><strong>St. John's Wort</strong></a> tincture to evaporate water from the ear canal.$$
WHERE id = 79;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Wood Betony</strong> (Stachys officinalis) is a <strong>grounding</strong>, <strong>calming</strong>, and <strong>nervine</strong> herb — grounds vata; supports a sense of self-love and embodiment. Per Easley's monograph: indicated for rootedness and groundedness in the solar plexus; for dissociation with anxiety. For <strong>headaches</strong>: drains stagnant energy from the head; good for head pain and stress-induced migraines. Work with the leaves.$$
WHERE id = 207;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Wormwood</strong> is the <strong>most bitter</strong> of the herbs (per class bitters tasting) — a <strong>cooling bitter</strong>, <strong>anthelmintic</strong>, and <strong>digestive</strong> herb with a history in witch's flying ointment and absinthe. For <strong>GI-based depression</strong>: bitter digestive to support the enteric brain; "use when patient is ready for deep work" — carries underworld/shadow energy; for stagnation picture. For <strong>digestion</strong>: stimulates HCL, pancreatic juices, and bile secretions; cooling bitter for hypochlorhydria. For <strong>parasites</strong>: anthelmintic — removes amoebas, tapeworms, and GI worms; high doses require proper elimination support (kidney support, watch for Herxheimer die-off reaction). For <strong>pain</strong>: applied directly to skin for osteoarthritis and pain management. In <strong>Four Thieves Vinegar</strong>: antimicrobial.$$
WHERE id = 97;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Yarrow</strong> (Achillea millefolium) is a <strong>diaphoretic</strong>, <strong>hemostatic</strong>, <strong>astringent</strong>, <strong>antimicrobial</strong>, <strong>bitter</strong>, and <strong>vulnerary</strong> panacea herb — "hot to the 4th degree"; a boundary plant and energetic protector; an essential herb of the Middle Ages in western Europe. For <strong>menorrhagia and fibroids</strong>: hemostatic, reduces blood flow; tincture 10–40 drops, infusion 2–4 oz; blend with <a href="?herb=43"><strong>Nettles</strong></a> and <a href="?herb=155"><strong>Raspberry</strong></a> 2 weeks before menses to nourish uterine structures first (takes a few cycles). Styptic: yarrow powder applied directly to stop bleeding. Emmenagogue: stimulates menstruation if already on the way. For <strong>fever</strong>: diaphoretic panacea; encourages blood flow to the skin; cools the blood, clears heat. For <strong>wounds</strong>: serves all three wound wash roles — astringent (with <a href="?herb=981"><strong>Red Root</strong></a> leaf), antimicrobial (with Tea Tree, Rosemary, <a href="?herb=59"><strong>Thyme</strong></a>, Oregano), and vulnerary (with <a href="?herb=85"><strong>Plantain</strong></a>, <a href="?herb=70"><strong>Calendula</strong></a>, <a href="?herb=82"><strong>Lavender</strong></a>, <a href="?herb=84"><strong>Chamomile</strong></a>, <a href="?herb=2437"><strong>Self Heal</strong></a>, <a href="?herb=88"><strong>Chickweed</strong></a>, <a href="?herb=81"><strong>St. John's Wort</strong></a>); for bites, stings, and splinters; postpartum tissue repair; burns: anti-inflammatory, demulcent, emollient. For <strong>urinary</strong>: antiseptic, kills bacteria in the urinary tract; diaphoretic and diuretic; anti-inflammatory. For <strong>digestion</strong>: medium bitter with strong volatile oil (both bitter and carminative); GI astringent and antimicrobial for diarrhea; heals gastric mucosa (peptic ulcer). For <strong>respiratory</strong>: in the Deep Lung Formula for bronchitis alongside <a href="?herb=54"><strong>Elecampane</strong></a>, <a href="?herb=65"><strong>Angelica</strong></a>, <a href="?herb=590"><strong>Yerba Santa</strong></a>, <a href="?herb=1652"><strong>Hawthorn</strong></a>, <a href="?herb=61"><strong>Mullein</strong></a>, <a href="?herb=309"><strong>Yerba Mansa</strong></a>, <a href="?herb=21"><strong>Garlic</strong></a>, <a href="?herb=104"><strong>Osha</strong></a>. Formulas: "Strengthen and Repair" (<a href="?herb=45"><strong>Marshmallow</strong></a>, <a href="?herb=92"><strong>Slippery Elm</strong></a>, Yarrow); regenerative tea with <a href="?herb=151"><strong>Horsetail</strong></a>, <a href="?herb=95"><strong>Corn Silk</strong></a>, <a href="?herb=43"><strong>Nettle</strong></a>, <a href="?herb=1014"><strong>Lady's Mantle</strong></a>, <a href="?herb=2233"><strong>Hibiscus</strong></a>, <a href="?herb=42"><strong>Red Clover</strong></a>; sitz bath and perineal wash with <a href="?herb=70"><strong>Calendula</strong></a>, <a href="?herb=85"><strong>Plantain</strong></a>, Rose, Yarrow. Heart bypass support: keeps the body calm so the brain signals more efficiently. <strong>Energetically</strong>: thickens the emotional membrane; gentle energetic protection for practitioners before client sessions.$$
WHERE id = 44;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Yellow Dock</strong> (Rumex crispus) is an <strong>alterative</strong>, <strong>aperient</strong>, <strong>bitter</strong>, <strong>cholagogue</strong>, and <strong>hepatic</strong> herb — mineral-rich and supportive for iron assimilation. Yellow color indicates bile; stagnation tends toward constipation. For <strong>constipation</strong>: primary indication; gentle aperient and stool softener, not habit-forming; gentler than senna; 50–60 drops; addresses chemical detox and constipation together; for constipation in pregnancy (final escalation from marshmallow and dandelion root). For <strong>anemia and iron</strong>: helps the body assimilate iron (even though it contains no iron itself); Iron Tonic Syrup for pregnancy (1 T dried root); Molasses Yellow Dock Syrup — pair with Vitamin C, dried fruits, or <a href="?herb=849"><strong>Rose Hips</strong></a> for iron metabolism. For <strong>liver and bile</strong>: both choleretic and cholagogue; hepatic for elimination and detox alongside <a href="?herb=17"><strong>Schizandra</strong></a>, <a href="?herb=206"><strong>Milk Thistle</strong></a>, <a href="?herb=43"><strong>Nettle</strong></a>, <a href="?herb=42"><strong>Red Clover</strong></a>, <a href="?herb=28"><strong>Cleavers</strong></a>; improves fat absorption in liver deficiency. For <strong>rheumatoid arthritis</strong>: alterative, digestive bitter, and hepatic. For <strong>psoriasis</strong>: David Hoffmann formula with <a href="?herb=22"><strong>Burdock</strong></a> and Baical Skullcap. Alterative formula for excess androgens: <a href="?herb=22"><strong>Burdock</strong></a>, Figwort, Sarsaparilla, Yellow Dock. Lower GI deficiency (dry/constipative): <a href="?herb=34"><strong>Bogbean</strong></a>, <a href="?herb=167"><strong>Cinnamon</strong></a>, <a href="?herb=78"><strong>Licorice</strong></a>, Yellow Dock; (congestive/stagnation): <a href="?herb=1248"><strong>Ocotillo</strong></a>, <a href="?herb=24"><strong>Fringetree</strong></a>, Yellow Dock. Digestion decoction recipe: 14g <a href="?herb=76"><strong>Fennel</strong></a>, 28g Yellow Dock, 28g <a href="?herb=54"><strong>Elecampane</strong></a>. Mineral-rich: suitable for extended infusion (4 hours). <strong>Preparation</strong>: requires decoction with heat for proper extraction (active constituents not water-soluble without heat); glycerite or syrup helps mask difficult taste; use root only. Dose: 30–75 drops 3x/day (MM range).$$
WHERE id = 37;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Yellow Pond Lily</strong> Root is an <strong>astringent</strong> and <strong>cooling</strong> herb used for <strong>hot, damp diarrhea</strong> and sudden-onset diarrhea. Also used to cool the system in <strong>reproductive excess</strong> conditions — both female and male.$$
WHERE id = 2627;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Yerba Mansa</strong> (Anemopsis californica) is a <strong>warming</strong>, <strong>anticatarrhal</strong>, <strong>astringent</strong>, <strong>antimicrobial</strong>, and <strong>lymphagogue</strong> herb — tannin-rich; stimulates immune function in the mucus membranes; moistening for dry cough. For <strong>upper respiratory</strong>: thins mucus secretions and reduces congestion; for stuffy and runny nose; hay fever (decoction, or small amount of tincture in neti pot); for asthma (anticatarrhal) and spasmodic cough; always consider for mucus membrane support in chronic respiratory cases. Anticatarrhal group: Yerba Mansa, <a href="?herb=30"><strong>Goldenseal</strong></a>, <a href="?herb=21"><strong>Garlic</strong></a>, <a href="?herb=50"><strong>Boneset</strong></a>. In the Deep Lung Formula for bronchitis alongside <a href="?herb=54"><strong>Elecampane</strong></a>, <a href="?herb=65"><strong>Angelica</strong></a>, <a href="?herb=590"><strong>Yerba Santa</strong></a>, <a href="?herb=44"><strong>Yarrow</strong></a>, <a href="?herb=1652"><strong>Hawthorn</strong></a>, <a href="?herb=61"><strong>Mullein</strong></a>, <a href="?herb=21"><strong>Garlic</strong></a>, <a href="?herb=104"><strong>Osha</strong></a>. Neti pot: use as the liquid base when infection is present. For <strong>lymph/immune deficiency</strong>: lymphagogue. For <strong>wound wash</strong>: antimicrobial. Note: less effective than stimulating expectorants for deep-seated mucus.$$
WHERE id = 309;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Yerba Santa</strong> is a <strong>warming</strong>, <strong>drying</strong>, and <strong>stimulating expectorant</strong> herb — "super drying"; specifically indicated for <strong>bronchitis</strong> and <strong>cold and damp cough</strong>. For <strong>cold and damp lung</strong>: stimulating expectorant alongside <a href="?herb=104"><strong>Osha</strong></a> and <a href="?herb=2231"><strong>Grindelia</strong></a>. Decongestant for asthma and allergic reactions. In the Deep Lung Formula for bronchitis alongside <a href="?herb=54"><strong>Elecampane</strong></a>, <a href="?herb=65"><strong>Angelica</strong></a>, <a href="?herb=44"><strong>Yarrow</strong></a>, <a href="?herb=1652"><strong>Hawthorn</strong></a>, <a href="?herb=61"><strong>Mullein</strong></a>, <a href="?herb=309"><strong>Yerba Mansa</strong></a>, <a href="?herb=21"><strong>Garlic</strong></a>, <a href="?herb=104"><strong>Osha</strong></a>. <strong>Preparation</strong>: resinous constituents do not extract well in water — decoction not appropriate; alcohol extraction preferred (the same applies to <a href="?herb=2231"><strong>Grindelia</strong></a>, <a href="?herb=1597"><strong>Frankincense</strong></a>, and <a href="?herb=99"><strong>Myrrh</strong></a>).$$
WHERE id = 590;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Ylang Ylang</strong> is a <strong>smooth muscle antispasmodic</strong> included in the threatened miscarriage protocol alongside <a href="?herb=93"><strong>Cramp Bark</strong></a>.$$
WHERE id = 745;
